	protected void emitFindAllAuditProgram( AuditProgram entity ) {
		LOGGER.info("handling emitFindAllAuditProgram" );
		
	    queryUpdateEmitter.emit(FindAllAuditProgramQuery.class,
	                            query -> true,
	                            entity);
	}

